const menus={halim:[['حلیم سنتی تبریز','گندم، گوشت و زمان؛ با دارچین، کنجد و کره، به سلیقه شما.','پیشنهاد ما'],['حلیم با کره و دارچین','همان طعم آشنا، با عطر دارچین و گرمای کره روی حلیم.','خوش‌عطر'],['حلیم برای سفره خانواده','یک انتخاب برای صبح‌های دورهمی؛ همراه مخلفات حلیم.','دورهمی']],breakfast:[['نان و پنیر ایرانی','نان تازه، پنیر، گردو و سبزی؛ ساده و همیشه دوست‌داشتنی.','کلاسیک'],['خامه و عسل','شیرینی عسل در کنار خامه، برای یک شروع آرام.','شیرین'],['مخلفات حلیم','دارچین، کنجد، شکر یا نمک؛ طعم حلیم به انتخاب شما.','به سلیقه شما']],tea:[['چای ایرانی','چای دم‌کشیده در استکان؛ همراه همیشگی سفره صبحانه.','خوش‌عطر'],['چای دارچین','یک فنجان چای گرم با عطر آرام دارچین.','گرم'],['دمنوش زعفران','عطر زعفران و رنگ طلایی، برای لحظه‌ای مکث.','طلایی']]};
const panel=document.querySelector('#menu-items');function renderMenu(category){panel.innerHTML=menus[category].map(([name,description,tag])=>`<article class="menu-item"><div class="item-title"><h3>${name}</h3><span class="dots"></span><span class="tag">${tag}</span></div><p>${description}</p></article>`).join('')}renderMenu('halim');const tabs=[...document.querySelectorAll('[data-category]')];tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>{tabs.forEach(t=>t.setAttribute('aria-selected',String(t===tab)));renderMenu(tab.dataset.category)});tab.addEventListener('keydown',event=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();let next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowLeft'?1:-1)+tabs.length)%tabs.length;tabs[next].focus();tabs[next].click()}})});const toggle=document.querySelector('.mobile-toggle'),nav=document.querySelector('nav');toggle.addEventListener('click',()=>{const open=nav.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'بستن منو':'باز کردن منو');toggle.textContent=open?'×':'☰'});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.textContent='☰'}));
